import manifest from '../../data/image-manifest.json';

const imageUrl = (name, width) => `${import.meta.env.BASE_URL}images/${name}-${width}.webp`;

// srcset for a manifest slug, e.g. for a <source> inside a <picture>.
export const srcSetFor = (name) => manifest[name]?.widths.map((w) => `${imageUrl(name, w)} ${w}w`).join(', ');

// Responsive <img> for the artwork generated by scripts/optimize-images.mjs.
// `name` is a manifest slug. Intrinsic width/height are always set so the
// browser reserves space before the file arrives. Images lazy-load unless
// `priority` (above-the-fold, fetched first) or `loading="eager"` is passed.
export default function Picture({ name, alt, sizes = '100vw', priority = false, ...rest }) {
  const meta = manifest[name];

  if (!meta) {
    if (import.meta.env.DEV) console.warn(`Picture: unknown image "${name}"`);
    return null;
  }

  const srcSet = meta.widths.map((w) => `${imageUrl(name, w)} ${w}w`).join(', ');
  const fallback = meta.widths.find((w) => w >= 800) ?? meta.widths.at(-1);

  return (
    <img
      src={imageUrl(name, fallback)}
      srcSet={srcSet}
      sizes={sizes}
      width={meta.width}
      height={meta.height}
      alt={alt}
      loading={priority ? 'eager' : 'lazy'}
      decoding={priority ? 'sync' : 'async'}
      fetchPriority={priority ? 'high' : undefined}
      {...rest}
    />
  );
}
